package com.example.rti;
import java.time.LocalDate; import java.util.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/rti") public class RtiRequestController {
 private final RtiRequestRepository requests;private final AppUserRepository users;
 public RtiRequestController(RtiRequestRepository r,AppUserRepository u){requests=r;users=u;}
 private AppUser current(Authentication a){return users.findByEmailIgnoreCase(a.getName()).orElseThrow();}
 private boolean officer(Authentication a){return a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_OFFICER"));}
 @GetMapping public List<RtiRequest> all(Authentication a){return officer(a)?requests.findAll():requests.findByOwnerId(current(a).getId());}
 @PostMapping public ResponseEntity<?> create(@Valid @RequestBody RtiRequest r,Authentication a){r.setRequestCode("RTI-"+UUID.randomUUID().toString().substring(0,8).toUpperCase());r.setSubmissionDate(LocalDate.now());r.setDeadlineDate(LocalDate.now().plusDays(30));r.setStatus("SUBMITTED");r.setResponse(null);r.setResponseDate(null);r.setOwner(current(a));return ResponseEntity.status(201).body(requests.save(r));}
 @GetMapping("/{code}") public ResponseEntity<?> track(@PathVariable String code,Authentication a){var f=requests.findByRequestCode(code);if(f.isEmpty())return ResponseEntity.status(404).body(Map.of("error","Request not found."));RtiRequest r=f.get();if(!officer(a)&&(r.getOwner()==null||!r.getOwner().getId().equals(current(a).getId())))return ResponseEntity.status(403).body(Map.of("error","You cannot access another citizen's request."));return ResponseEntity.ok(r);}
 @PutMapping("/{code}/status") public ResponseEntity<?> update(@PathVariable String code,@RequestBody Map<String,String>d){var f=requests.findByRequestCode(code);if(f.isEmpty())return ResponseEntity.status(404).body(Map.of("error","Request not found."));String s=d.get("status");if(s==null||!List.of("SUBMITTED","UNDER_REVIEW","RESPONDED").contains(s))return ResponseEntity.badRequest().body(Map.of("error","Invalid status."));RtiRequest r=f.get();if("RESPONDED".equals(s)){String reply=d.get("response");if(reply==null||reply.isBlank())return ResponseEntity.badRequest().body(Map.of("error","Response is required."));r.setResponse(reply.trim());r.setResponseDate(LocalDate.now());}else{r.setResponse(null);r.setResponseDate(null);}r.setStatus(s);return ResponseEntity.ok(requests.save(r));}
 @GetMapping("/summary") public Map<String,Long> summary(){List<RtiRequest> l=requests.findAll();LocalDate d=LocalDate.now();long total=l.size(),responded=l.stream().filter(x->"RESPONDED".equals(x.getStatus())).count(),overdue=l.stream().filter(x->!"RESPONDED".equals(x.getStatus())).filter(x->x.getDeadlineDate()!=null&&x.getDeadlineDate().isBefore(d)).count(),soon=l.stream().filter(x->!"RESPONDED".equals(x.getStatus())).filter(x->x.getDeadlineDate()!=null&&!x.getDeadlineDate().isBefore(d)&&!x.getDeadlineDate().isAfter(d.plusDays(7))).count();Map<String,Long> m=new LinkedHashMap<>();m.put("total",total);m.put("pending",total-responded);m.put("responded",responded);m.put("overdue",overdue);m.put("dueSoon",soon);return m;}
}